import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"橘颂","description":"","frontmatter":{"title":"橘颂","date":"2026-11-24T00:00:00.000Z","seq":21,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"惜往日","link":"/blogs/楚辞/惜往日.html"},"next":{"text":"悲回风","link":"/blogs/楚辞/悲回风.html"}},"headers":[],"relativePath":"blogs/楚辞/橘颂.md","filePath":"blogs/楚辞/橘颂.md"}'),o={name:"blogs/楚辞/橘颂.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="橘颂" tabindex="-1">橘颂 <a class="header-anchor" href="#橘颂" aria-label="Permalink to &quot;橘颂&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">后皇嘉树，橘徕服兮。</p><p class="poem-stanza">受命不迁，生南国兮。</p><p class="poem-stanza">深固难徙，更壹志兮。</p><p class="poem-stanza">绿叶素荣，纷其可喜兮。</p><p class="poem-stanza">曾枝剡棘，圆果抟兮。</p><p class="poem-stanza">青黄杂糅，文章烂兮。</p><p class="poem-stanza">精色内白，类任道兮。</p><p class="poem-stanza">纷緼宜修，姱而不丑兮。</p><p class="poem-stanza">嗟尔幼志，有以异兮。</p><p class="poem-stanza">独立不迁，岂不可喜兮？</p><p class="poem-stanza">深固难徙，廓其无求兮。</p><p class="poem-stanza">苏世独立，横而不流兮。</p><p class="poem-stanza">闭心自慎，终不失过兮。</p><p class="poem-stanza">秉德无私，参天地兮。</p><p class="poem-stanza">愿岁并谢，与长友兮。</p><p class="poem-stanza">淑离不淫，梗其有理兮。</p><p class="poem-stanza">年岁虽少，可师长兮。</p><p class="poem-stanza">行比伯夷，置以为像兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
